from typing import Dict, List, Optional, Tuple, Union


def find_item(items: List[dict], sku: str) -> Optional[dict]:
    for item in items:
        if item["sku"] == sku:
            return item
    return None


def stock_by_location(items: List[dict]) -> Dict[str, int]:
    totals: Dict[str, int] = {}
    for item in items:
        totals[item["location"]] = totals.get(item["location"], 0) + item["qty"]
    return totals


def bounds(values: List[int]) -> Tuple[int, int]:
    return min(values), max(values)


def parse_qty(raw: Union[str, int]) -> int:
    return int(raw)

