from inventory.models import bounds, find_item, parse_qty, stock_by_location

ITEMS = [
    {"sku": "a", "location": "north", "qty": 2},
    {"sku": "b", "location": "north", "qty": 3},
    {"sku": "c", "location": "south", "qty": 1},
]


def test_find_item():
    assert find_item(ITEMS, "b")["qty"] == 3
    assert find_item(ITEMS, "zzz") is None


def test_stock_by_location():
    assert stock_by_location(ITEMS) == {"north": 5, "south": 1}


def test_bounds():
    assert bounds([4, 1, 9]) == (1, 9)


def test_parse_qty():
    assert parse_qty("7") == 7
    assert parse_qty(7) == 7
